"""Render the final report from derived measurements; no experiment execution."""
import json
from pathlib import Path

H = Path(__file__).resolve().parent
load = lambda name: json.loads((H/name).read_text())
detail = load('pooled-detail.json')
m = load('measurements.json')
validation = load('VALIDATION.json')
repeats = load('repeatability.json')
profiles = load('profile-detail.json')
selected = lambda phase, workload, policy: next(x for x in detail if (x['phase'],x['workload'],x['policy']) == (phase,workload,policy))
fmt = lambda x, n=2: 'unavailable' if x is None else f'{x:,.{n}f}'
ms = lambda x: None if x is None else x*1000
pct = lambda sem,arc: (sem/arc-1)*100
lines = []
def p(text=''): lines.extend([text,''])
def table(head, rows):
    p('| '+' | '.join(head)+' |\n| '+' | '.join('---' for _ in head)+' |\n'+'\n'.join('| '+' | '.join(str(x) for x in row)+' |' for row in rows))

p('# RTX 2080 Ti ARC and semantic agent workload results')
p('Measured on October 31 2026. With the repository’s representative generated agent workloads, full continuous semantic eviction plus enabled wait-hint prefetch is slower than ARC: **27.4% lower throughput for one agent and 19.2% lower for six agents**. The normal matrix completed all 378 requests and generated 28,800 tokens. This configuration has not demonstrated the project’s intended gain in useful exact cache reuse, latency, or resource efficiency.')
p('The features being enabled does not mean they had a useful opportunity. Normal runs had no CPU cache eviction and no submitted or consumed prefetch. A separate admission-stress matrix did exercise scored semantic eviction, but still produced no prefetch and no advantage. These are representative simulations of coding and investigation sessions, with generated tool outputs and background traffic; they are not production traces or measurements of an actual agent’s task success.')
p('## Primary workload matrix')
p('Each entry pools three fresh-server runs at seeds 1103, 2207 and 3301. Throughput is total completed output tokens divided by summed workload duration; latency percentiles pool individual requests rather than averaging per-run percentiles. TTFT means time from the request’s intended release to its first received token. ITL means the mean received intertoken interval; tokens delivered together in a network chunk share a receipt time, so this is client-observed streaming latency rather than isolated GPU token time. Smaller latency is better; larger throughput is better.')
table(['Workload','Policy','Requests','Output tokens/s','Mean TTFT s','Median TTFT s','p95 TTFT s','Mean ITL ms'],[
 [w,pol,d['all']['completed'],fmt(d['all']['output_tokens_s']),fmt(d['all']['release_ttft_ms']['mean']/1000),fmt(d['all']['release_ttft_ms']['median']/1000),fmt(d['all']['release_ttft_ms']['p95']/1000),fmt(d['all']['mean_itl_ms'])]
 for w in ['single','multi'] for pol in ['arc','semantic'] for d in [selected('main',w,pol)]])
table(['Workload','Semantic throughput change','Mean TTFT change','p95 TTFT change','ITL change','Throughput change across paired seeds'],[
 [w,fmt(pct(s['all']['output_tokens_s'],a['all']['output_tokens_s']))+'%',fmt(pct(s['all']['release_ttft_ms']['mean'],a['all']['release_ttft_ms']['mean']))+'%',fmt(pct(s['all']['release_ttft_ms']['p95'],a['all']['release_ttft_ms']['p95']))+'%',fmt(pct(s['all']['mean_itl_ms'],a['all']['mean_itl_ms']))+'%',fmt(min(cs))+'% to '+fmt(max(cs))+'%']
 for w in ['single','multi'] for a,s in [(selected('main',w,'arc'),selected('main',w,'semantic'))] for cs in [[x['throughput_delta_pct'] for x in m['comparisons'] if x['phase']=='main' and x['workload']==w]]])
p('Both workloads include the same twelve independent background requests per run. “Single” means one six-turn agent session plus those requests. “Multi” means six agent sessions, with five completing six turns and one abandoning after three turns, plus background traffic. Max active GPU sequences is three, so six agents create genuine queuing. The normal matrix contains 54 requests per policy for single and 135 per policy for multi. All three paired seeds favor ARC for throughput. The sample is small: the p95 values are descriptive tails, not a service guarantee or a significance test.')
p('## Agent and background latency')
table(['Workload','Policy','Role','Requests','Mean TTFT s','p95 TTFT s','Mean request elapsed s','Mean queue s','Mean service s'],[
 [w,pol,role,g['requests'],fmt(g['release_ttft_ms']['mean']/1000),fmt(g['release_ttft_ms']['p95']/1000),fmt(g['request_elapsed_ms']['mean']/1000),fmt(g['queue_ms']['mean']/1000),fmt(g['service_ms']['mean']/1000)]
 for w in ['single','multi'] for pol in ['arc','semantic'] for role in ['agent','background'] for g in [selected('main',w,pol)['groups'][role]]])
table(['Workload','Policy','Mean load duration s','Mean agent session completion s','Max agent session completion s','Mean release lateness ms'],[
 [w,pol,fmt(d['all']['elapsed_s']/d['runs']),fmt(d['agent_session_completion_ms']['mean']/1000),fmt(d['agent_session_completion_ms']['max']/1000),fmt(d['all']['release_lateness_ms']['mean'])]
 for w in ['single','multi'] for pol in ['arc','semantic'] for d in [selected('main',w,pol)]])
p('Agent arrivals are closed loop: a later turn follows the prior completion and its actual tool wait. Slower serving therefore changes batch and cache histories. Background arrivals are fixed relative to workload start. Session completion includes intervening waits and is measured from workload start; the abandoning session ends at its last successful LLM completion in this table. Request elapsed is submit to stream completion. Server queue and service timings come from preserved scheduler/connector records; they are not substitutes for client TTFT.')
p('## Cache work and feature activation')
table(['Workload','Policy','Executed prompt tokens','GPU hit tokens','CPU restored tokens','CPU stored blocks','CPU evicted blocks','Query captures','Rows in score updates','Prefetch jobs ready or consumed'],[
 [w,pol,f"{d['all']['executed_prompt_tokens']:,}",f"{d['all']['gpu_hit_tokens']:,}",d['all']['external_reused_tokens'],d['manager_counts'].get('store_completed_keys',0),d['manager_counts'].get('cpu_evicted_blocks',0),d['activation']['worker_capture_calls'],d['manager_counts'].get('relevance_scored_rows',0),f"{d['activation']['staging_jobs_ready']} / {d['activation']['prefetch_consumed_blocks']}"]
 for w in ['single','multi'] for pol in ['arc','semantic'] for d in [selected('main',w,pol)]])
table(['Workload','Policy','Demand H2D MiB','D2H MiB','Reported H2D worker ms','Reported D2H worker ms','Speculative H2D MiB','Preemptions'],[
 [w,pol,fmt(d['traffic']['demand_h2d_bytes']/2**20),fmt(d['traffic']['d2h_bytes']/2**20),fmt(ms(d['traffic']['demand_h2d_worker_s']),3),fmt(ms(d['traffic']['d2h_worker_s']),3),fmt(d['traffic']['prefetch_consumed_bytes']/2**20),d['activation']['preemptions']]
 for w in ['single','multi'] for pol in ['arc','semantic'] for d in [selected('main',w,pol)]])
p('H2D means host CPU memory to GPU; D2H is the reverse. Byte totals and reported worker durations sum terminal transfer attribution and can include repeated movement; they are not unique cache footprint or exclusive critical-path time. Transfer durations are unavailable when no job occurred. H2D durations vary substantially across ARC seeds (75, 696 and 213ms), while semantic totals are 11–14ms per seed; these CUDA event intervals are affected by the run’s execution/stream history and do not establish an isolated copy-bandwidth advantage. The normal single-agent run retains returning prefixes on GPU and never populates the CPU cache. Continuous scoring skips extraction when its durable CPU summary bank is empty, but the dispatch mode still surrounds model execution. Multi-agent runs restore a small amount of CPU KV. Their CPU caches never fill, so semantic eviction cannot improve retention here. Semantic executes 2.78% more prompt work in multi despite the same paired inputs: differing closed-loop scheduling/cache histories are part of the measured outcome, rather than a fixed-batch microbenchmark.')
table(['Workload','Policy','Peak ready CPU blocks','Minimum free GPU blocks','Peak referenced GPU blocks','Peak speculative reservations'],[
 [w,pol,max(s['cpu_peak_ready_blocks'] for s in ss),min(s['gpu_min_free_blocks'] for s in ss),max(s['gpu_peak_referenced_blocks'] for s in ss),max(s['gpu_peak_reserved_blocks'] for s in ss)]
 for w in ['single','multi'] for pol in ['arc','semantic'] for ss in [[s for s in m['summaries'] if (s['phase'],s['workload'],s['policy'])==('main',w,pol)]]])
p('Across all ordinary and stress runs, speculative nominations with candidates, submitted staging jobs, ready staging jobs, consumed staging blocks, GPU splice bytes, and speculative waste bytes are zero. No competitive semantic prefetch selection occurs. Prefetch lead time, fence-before-forward, delivery latency and waste efficiency are therefore unavailable as performance observations, not zero-duration successes. The full implementation was enabled; its usefulness under an actual prefetch opportunity remains unestablished on this host.')
p('Query captures count worker callback batches. Rows in score updates count rows delivered to the CPU manager, including repeated updates; they do not count every worker vector comparison. Detailed component counters retain those comparisons in the separate profiled runs.')
p('## Admission stress matrix')
p('The frozen protocol calls for this supplement if the normal matrix has no CPU eviction or no consumed prefetch. It changes only the admission threshold from two to zero in both arms at seed 1103, admitting one-use blocks. All other model, memory and workload controls remain unchanged. This diagnostic deliberately increases churn and is excluded from normal headline results.')
table(['Workload','Policy','Requests','Output tokens/s','Mean TTFT s','CPU stored blocks','CPU evicted blocks','Semantic eviction calls with score state','CPU restores','Prefetch consumed blocks'],[
 [w,pol,d['all']['completed'],fmt(d['all']['output_tokens_s']),fmt(d['all']['release_ttft_ms']['mean']/1000),d['manager_counts'].get('store_completed_keys',0),d['manager_counts'].get('cpu_evicted_blocks',0),d['manager_counts'].get('semantic_evict_calls_with_scores',0),d['all']['external_reused_tokens'],d['activation']['prefetch_consumed_blocks']]
 for w in ['single','multi'] for pol in ['arc','semantic'] for d in [selected('stress',w,pol)]])
for w in ['single','multi']:
    a,s=selected('stress',w,'arc'),selected('stress',w,'semantic')
    p(f"Semantic throughput changes by {fmt(pct(s['all']['output_tokens_s'],a['all']['output_tokens_s']))}% versus ARC in {w}. Its CPU cache reaches the full 199-block capacity. This is actual semantic eviction with nonempty scores, not merely a policy configuration flag.")
p('For the semantic multi stress run, hint responses include 60 prefixes already on GPU, 23 without a ready contiguous CPU prefix, and six expired nomination deadlines, alongside registration and unknown-event responses. No hint reaches a competitive selection. The code checks GPU coverage and the next ready exact CPU prefix before staging. This points toward useful prefix availability and admission/retention as a prerequisite to testing ranking quality. It does not prove one eviction rule caused every missed opportunity or that a faster search index would recover them. Removing the admission guard produces substantial CPU write traffic without useful restores in this trace.')
p('## CPU memory GPU and energy')
table(['Workload','Policy','Sampled CPU s','Peak summed RSS GiB','RSS GiB seconds','Mean GPU utilization %','CUDA allocated peak MiB','CUDA reserved peak MiB','Device peak GiB','Device energy kJ','J per output token'],[
 [w,pol,fmt(r['sampled_cpu_s']),fmt(r['sampled_rss_peak_gib']),fmt(r['sampled_rss_gib_seconds']),fmt(r['sampled_gpu_utilization_pct_weighted']),fmt(r['load_cuda_peak_allocated_mib']),fmt(r['load_cuda_peak_reserved_mib']),fmt(r['sampled_device_memory_peak_gib']),fmt(r['sampled_energy_j']/1000),fmt(r['sampled_energy_j_per_output_token'],3)]
 for w in ['single','multi'] for pol in ['arc','semantic'] for r in [selected('main',w,pol)['resources']]])
p('These totals cover the three measured load windows per cell. CPU/RSS and NVML samples are collected approximately every 250ms. Sampled process CPU is an estimate with recorded boundary overhang; short-lived or non-server work can be missed. Summed RSS can double-count shared pages. CUDA peaks reset after warmup and measure PyTorch allocations/reservations, while device memory includes driver/display allocations. Device energy integrates whole-device sampled power and includes non-model activity. Clocks use normal dynamic scaling, not locked frequencies. Raw power, clocks, temperature, utilization and process samples are preserved, so these are resource indicators rather than an isolated hardware-efficiency or provider-price claim. There is no measured VRAM or useful-capacity win.')
p('## Separate component profiles')
p('These four runs enable additional instrumentation and remain outside primary throughput and latency pooling. Instrumentation can enlarge or change the gap. Runner execution wall time and thread CPU time include nested preparation, Python dispatch, launches and callbacks; they overlap other reported components and must not be added together.')
rows=[]
for prof in sorted(profiles,key=lambda x:x['name']):
    times=prof['method_times'];exe=times.get('runner.execute_model',{});sc=times.get('worker._score_queries',{})
    counters={k:sum(e.get('counters',{}).get(k,0) for e in prof['component_exports']) for k in ['capture.dispatch_calls','logging.bytes']}
    metrics=lambda key:sum(e.get('metrics',{}).get(key,{}).get('total_ns',0) for e in prof['component_exports'])/1e9
    rows.append([prof['name'].replace('diagnostic-','').replace('-1103',''),fmt(prof['load_elapsed_s']),exe.get('calls',0),fmt(exe.get('host_wall_ns',0)/1e9),fmt(exe.get('thread_cpu_ns',0)/1e9),prof['capture'].get('calls',0),counters['capture.dispatch_calls'],fmt(sc.get('host_wall_ns',0)/1e9,3),fmt(metrics('logging.preservation.host_wall'),3)])
table(['Workload and policy','Load s','Runner calls','Runner wall s','Runner CPU s','Captured query batches','Dispatch interceptions','Score wall s','Preservation logging wall s'],rows)
p('The single-agent profile has no extracted query batches or score work, yet semantic runner execution consumes substantially more wall and CPU time and records 416,544 dispatch interceptions. Source inspection confirms that the empty-bank check occurs inside capture after model execution has already entered TorchDispatchMode. That makes bypassing capture machinery when no score can be consumed a strong candidate for a controlled ablation. It does not attribute the entire slowdown to the dispatch body or establish the speedup a change would deliver. Preparation, metadata, scheduler decisions, transfer polling, scoring, logging and sampled CUDA stream scopes are retained in components.csv and profile-detail.json. CUDA scopes sample every 16 calls and overlap host/other stream activity; their sums are neither exclusive attention-kernel time nor total GPU busy time. All final synchronized exports have no pending profile CUDA samples or async observations.')
p('The multi-agent semantic profile also spends 12.44s inside query scoring during its 71.26s load, despite the absence of eviction or prefetch consumption in that run. Scoring and capture therefore need separate cost ablations; the data do not justify attributing the whole gap to one component.')
p('## Output integrity and reliability')
p('Primary output lengths, successful completion and authoritative terminal coverage all match the fixed budgets. Every primary request has complete ordered native keys and physical block/table evidence. Transfer jobs in completed matrix cells report no failure. Exact paired outputs match for 183 of 189 primary request pairs. All 135 multi-agent pairs match exactly.')
p('The exception is single seed 2207. Its first agent request has identical input tokens, no GPU prefix hits and no external restore in either arm, but output first differs at token 58. Five later turns inherit different generated history. All twelve independent background outputs match. This initial divergence cannot have come from consuming an incorrect restored CPU cache on that request. Ordinary FP16 batching/numerics is a hypothesis; cache and inference correctness are not certified solely by that observation.')
table(['Separate comparison','Requests','Same prompts','Same outputs','Same ordered key chains'],[[r['left']+' versus '+r['right'],len(r['requests']),r['prompt_equal_count'],r['output_equal_count'],r['ordered_key_chains_equal_count']] for r in repeats])
orig_repeat=repeats[0]
if orig_repeat['output_equal_count'] < len(orig_repeat['requests']):
    p('The one separately declared ARC-only repeat also diverges from the original ARC output, while matching all 18 semantic prompts, outputs and ordered key chains exactly. This establishes baseline output instability in this ordinary FP16 test setup and supports treating cross-arm identity carefully. It does not prove every semantic path correct. The repeat remains separate and never replaces or contributes to the headline samples.')
else:
    p('The one separately declared ARC-only repeat reproduces the original ARC outputs. It does not resolve the semantic-arm divergence or prove a semantic defect. Stronger fixed-history numerical and cache correctness isolation is still needed. The repeat remains separate and never replaces or contributes to headline samples.')
p('The first ARC multi profile had one immediate ServerDisconnectedError: 42 requests succeeded, one failed, and two dependent turns were never submitted. Other sessions continued and the engine exported successfully; a stale keep-alive connection is plausible but unproven. The first semantic multi profile completed all 45 requests, then failed in the post-load log reader on a partial JSON record before synchronized export. Both attempts remain under failed-attempts and are excluded from serving aggregates. ARC was repeated unchanged; semantic was repeated with only a tolerant post-load reader. A launcher import-path error before server startup is also preserved in continuation2.log. No primary run was replaced. The final successful matrix comprises 21 cells and 648 requests including stress, profiles and the separate repeat.')
p('The selected CPU regression suite passes 419 tests with CUDA initialization forbidden, using the same task-local runtime overlay and passive wrappers. Earlier failed guard/runtime setup attempts are retained alongside the final receipt. This is targeted regression evidence, not a production release qualification. See VALIDATION.json, repeatability.json, DIAGNOSTIC-RETRY.md and cpu-validation-final.log.')
p('## Configuration and comparability')
p('The model is Qwen2.5-1.5B-Instruct, FP16, TP1, eager Triton attention, V2 runner, WSL mapped pinned memory. Both policies use max model length 8192, three running sequences, 1024 batched tokens, 16-token blocks, 640 GPU blocks (280 MiB KV) and 199 CPU blocks (87.0625 MiB KV). The native null block reduces usable GPU entries by one. These deliberately small controlled KV pools create pressure; they do not use the whole 11 GiB GPU as cache or measure a memory-capacity frontier. Weights and all other allocations sit outside those KV budgets.')
p('ARC uses the stock ARCCachePolicy through the common instrumented connector, with query capture/scoring and speculative prefetch disabled. Semantic uses the real SemanticPolicy with mean keys/heads, default alpha 0.5 blend, continuous synchronous flat scoring at stride one, and semantic wait-hint selection with a 5% staging allowance inside the same GPU pool. Both use admission threshold two in the main matrix. Safe prefix-preserving staging is enabled as an experimental opt-in; native adoption is disabled because the current BF16-only guard excludes this FP16 GPU. Thus this tests the full available FP16 semantic eviction/prefetch configuration, not every experimental BF16 delivery path or the pure default allocator option.')
p('The policy receives a causally observed initial exact prefix and a fixed 250ms tool-wait estimate. Actual generated waits of 75–2400ms and abandonment are private to the load generator. It does not receive future tool outputs, actual wait deadlines or future reuse labels. Input preparation, model download, startup, the identical 16-token warmup and post-load synchronized exports are excluded from client throughput. End-to-end closed-loop duration includes tool-idle gaps between requests. Required preservation logging, passive method counters/timing and resource samples are included symmetrically, so these are instrumented serving results.')
p('The installed vLLM prerelease needs retained wait-hint utility forwarding methods. A pinned task-local five-module overlay supplies these and the existing companion block-pool API; the shared wheel and production checkout are unchanged. Runtime, source, model revision, generated inputs, commands and environment are pinned in the evidence. This setup is narrower than broad library compatibility.')
p('The tested source is the copied working checkout, including its pre-existing uncommitted changes. Its local branch tracking state was two commits behind origin/main at capture; no pull or source update was performed during this controlled comparison. These results describe the pinned working state rather than an unverified latest remote revision.')
p('The earlier near-parity result documented in README used ARC retention with opportunistic, sampled semantic prefetch scoring, and a different host/model/workload. It did not establish full semantic retention parity or competitive semantic ranking utility. The new matrix intentionally restores full continuous semantic retention and scoring. Its gap is therefore not a controlled regression from that older number, nor can the older result override these measurements.')
p('## Work needed toward the end goal')
p('The end goal is to save useful exact KV work at equal memory and acceptable latency/CPU cost. The current state provides an integrated experimental path and detailed accounting, but this host’s representative sessions show overhead without a useful prefetch opportunity. The following priorities follow from these measurements; they are proposed work, not changes made during this benchmark.')
p('1. **Make the inactive path cheap.** Ablate dispatch/layout/callback machinery when the durable bank is empty or no decision can consume a score. Preserve lifecycle accounting and compare the full configuration against the cheaper ARC-retention opportunity mode under identical controls. Acceptance requires preserved correctness plus reduced ordinary-workload CPU/latency cost, not only faster microkernels.\n2. **Create and preserve useful exact CPU prefixes economically.** Instrument why the next contiguous prefix disappears, then study admission and chain retention while retaining the threshold-two control. Holdout traces must actually have positive CPU-prefix opportunities and real prefetch consumption; measure writes, displacement, misses and downstream prompt work. Do not remove the admission guard simply to make eviction counters increase.\n3. **Test whether semantic ranking earns its cost.** Only after multiple eligible sources genuinely compete for a limited budget, compare semantic selection with matched ARC retention, demand-only and simple prefetch controls. Measure useful consumed bytes, ready-before-demand lead time, duplicate/wasted traffic, first-token latency and executed prompt tokens. An isolated faster search index cannot establish ranking utility here.\n4. **Resolve numerical repeatability and expand qualification.** Use fixed-history/fixed-batch cache-on/off isolation for the divergent request. Then use longer independent traces and a multi-point equal-memory/service-target capacity comparison, followed by a real application trace. Three short generated seeds and a small 1.5B model do not establish production readiness or paid-task quality.')
p('## Evidence and reproduction')
p('All results and large raw logs remain in this ignored output directory; no production code was changed, committed or pushed. The report tables are generated from pooled-detail.json and measurements.json. Per-request CSV preserves timestamps-derived latency, cache/transfer evidence and nulls for unavailable metrics; per-run raw JSON preserves prompts, outputs, hints, commands, process/device samples and terminal events. Server logs and raw JSON are losslessly compressed with verification receipts.')
p('- [Frozen protocol](PROTOCOL.md), [environment](environment.json), [pins](frozen.json), [runtime overlay](runtime-overlay.patch) and source recovery snapshot.\n- [All per-run results](runs.csv), [paired comparisons](comparisons.csv), [per-request metrics](requests.csv), [full aggregates](measurements.json), [pooled role and resource detail](pooled-detail.json).\n- [Component metrics](components.csv), [selected profile exports](profile-detail.json), [correctness and configuration audit](VALIDATION.json), [repeatability](repeatability.json), [failed-attempt summaries](failed-attempt-summary.json).\n- [CPU validation receipt](cpu-validation-final.json), [diagnostic retry explanation](DIAGNOSTIC-RETRY.md), [output validation addendum](VALIDATION-ADDENDUM.md), [storage and process handback](STORAGE.json).')
p('Use the project virtual environment. setup.py reconstructs the isolated runtime seam; run.py prepares and executes fresh cells, execute.py records the original finite ordering, and continuation scripts preserve the diagnostic recovery sequence. Existing run directories are never overwritten: archive the whole task directory and update the task path for a new campaign before re-execution. analyze.py, postprocess.py and report.py only regenerate derived data/report from preserved evidence. Source pins guard against comparing a changed checkout silently. The separate diagnostic_retry.py alters only the post-load log reader, and should not be confused with a product change.')
if (H/'STORAGE.json').exists():
    storage=load('STORAGE.json')
    p(f"Storage handback retains approximately {fmt(storage['retained'][0]['logical_bytes']/2**20,1)} MiB of evidence and {fmt(storage['retained'][1]['logical_bytes']/2**30,2)} GiB of reusable model content. Lossless compression reduced {fmt(storage['existing_compression']['uncompressed_bytes']/2**20,1)} MiB of raw JSON/logs to {fmt(storage['existing_compression']['compressed_bytes']/2**20,1)} MiB. Disposable task bytecode was removed; the interrupted profile write contains unique counters and was preserved. WSL free bytes changed from {storage['free_bytes_before']:,} to {storage['free_bytes_after']:,} during cleanup, an observed increase of {storage['observed_free_delta_bytes']:,} bytes. All sampled owned process identities are gone, the benchmark port is closed, the GPU lock is free and device utilization is zero at handback. Windows backing-volume reclaim was not measured. Shared caches remain available for reuse.")
(H/'REPORT.md').write_text('\n'.join(lines))
print('REPORT.md written')
